from pathlib import Path

# production.rb tweaks
p = Path("config/environments/production.rb")
text = p.read_text()
text = text.replace("config.assume_ssl = true", "config.assume_ssl = false")
text = text.replace("config.force_ssl = true", "config.force_ssl = false")
text = text.replace("config.cache_store = :solid_cache_store", "config.cache_store = :memory_store")
text = text.replace("config.active_job.queue_adapter = :solid_queue\n  config.solid_queue.connects_to = { database: { writing: :queue } }",
                    "config.active_job.queue_adapter = :async")
# serve static files and accept any host over plain HTTP
old = """  # Enable DNS rebinding protection and other `Host` header attacks.
  # config.hosts = [
  #   "example.com",     # Allow requests from example.com
  #   /.*\\.example\\.com/ # Allow requests from subdomains like `www.example.com`
  # ]
  #
  # Skip DNS rebinding protection for the default health check endpoint.
  # config.host_authorization = { exclude: ->(request) { request.path == "/up" } }
end
"""
new = """  # Quizzy is served over plain HTTP and must accept any Host header.
  config.hosts.clear
  config.public_file_server.enabled = true
  config.action_controller.forgery_protection_origin_check = false
end
"""
if old not in text:
    raise SystemExit("production.rb tail not found")
text = text.replace(old, new)
p.write_text(text)
print("production.rb updated")

db = Path("config/database.yml")
db.write_text("""# SQLite. Versions 3.8.0 and up are supported.
default: &default
  adapter: sqlite3
  max_connections: <%= ENV.fetch("RAILS_MAX_THREADS") { 5 } %>
  timeout: 5000

