  <<: *default
  database: storage/development.sqlite3

test:
  <<: *default
  database: storage/test.sqlite3

production:
  <<: *default
  database: storage/production.sqlite3
""")
print("database.yml written")

puma = Path("config/puma.rb")
puma_text = puma.read_text()
puma_text = puma_text.replace(
    'port ENV.fetch("PORT", 3000)',
    '# Listen on all interfaces. bin/serve sets PORT.\nbind "tcp://0.0.0.0:#{ENV.fetch(\'PORT\', 3000)}"'
)
puma.write_text(puma_text)
print("puma.rb updated")
